# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Model bahasa multibahasa memiliki keterbatasan dalam menghasilkan teks bahasa Indonesia yang natural, koheren, dan kontekstual." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Pemrosesan Bahasa Alami (Natural Language Processing) – Fokus pada Bahasa Indonesia dan Generasi Teks" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Model Generatif Berbasis Transformator untuk Sintesis Teks Bahasa Indonesia" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "- Pengembangan model generatif dengan arsitektur Transformator (Transformer‑XL)- Pra‑pelatihan pada korpus 150 juta token yang mencakup berita, blog, dan literatur Indonesia- Fine‑tuning pada tugas penulisan esai akademik" .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Korpus 150 juta token yang diambil dari sumber berita, blog, dan literatur Indonesia" .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "- Pengukuran otomatis menggunakan metrik BLEU dan ROUGE- Penilaian manusia terhadap kelancaran dan relevansi teks- Perbandingan dengan model baseline" .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Skor BLEU meningkat sebesar 9,4 poin dibandingkan model baseline" .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Skor rata‑rata penilaian manusia naik dari 3,2 menjadi 4,1 pada skala 5" .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Model menunjukkan kemampuan yang lebih baik dalam menghasilkan teks yang tepat secara linguistik dan semantik." .

