:Hasil :menunjukkanPeningkatanMap10Sebesar15 :8_Dibandingkan_Collaborative_Filtering_Tunggal .
:Hasil :menunjukkanPeningkatanNdcg10Sebesar13 :4_Dibandingkan_Collaborative_Filtering_Tunggal .
:Peningkatan_Map10 :menunjukkan :Efektivitas_Kombinasi_Teknik_Ai .
:Peningkatan_Ndcg10 :menunjukkan :Efektivitas_Kombinasi_Teknik_Ai .

# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Mengatasi masalah cold‑start dan sparsitas data interaksi pengguna pada platform e‑commerce yang menghambat efektivitas sistem rekomendasi." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Recommender Systems / E‑Commerce / Machine Learning" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Pengembangan Sistem Rekomendasi Hybrid untuk Platform E‑Commerce" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Hybrid recommendation yang menggabungkan collaborative filtering berbasis matrix factorization dengan content‑based filtering menggunakan word embeddings; pelatihan Factorization Machine; penggunaan model FastText untuk menghasilkan embedding produk." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Dataset transaksi yang berisi 1,2 juta pengguna dan 250 ribu produk." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Evaluasi dengan metrik MAP@10 dan NDCG@10 pada set uji terpisah; perbandingan dengan pendekatan collaborative filtering tunggal." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "MAP@10 meningkat sebesar 15,8 % dibandingkan collaborative filtering tunggal." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "NDCG@10 meningkat sebesar 13,4 % dibandingkan collaborative filtering tunggal." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Kombinasi teknik AI (matrix factorization + word embeddings) terbukti efektif meningkatkan relevansi rekomendasi pada platform e‑commerce." .

