# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Pemeliharaan mesin tradisional sering mengandalkan inspeksi periodik yang tidak efisien." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Manufaktur / Pemeliharaan Prediktif / Pembelajaran Mesin" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Model Prediktif untuk Pemeliharaan Mesin Menggunakan Data Sensor Industri" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Kerangka kerja prediktif berbasis pembelajaran mesin; ekstraksi fitur dengan teknik transformasi wavelet; pemilihan fitur melalui analisis pentingnya fitur; pembangunan dan perbandingan model Gradient Boosting serta Long Short‑Term Memory (LSTM)." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data sensor suhu, getaran, dan tekanan yang dikumpulkan selama 12 bulan dari 25 unit mesin pada lini produksi manufaktur." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Evaluasi performa model menggunakan metrik AUC‑ROC dan F1‑score; perbandingan dengan metode statistik tradisional; pengujian prototipe pada sistem kontrol real‑time selama tiga bulan untuk mengukur penurunan downtime." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Model LSTM mencapai AUC‑ROC 0.93." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "LSTM mengurangi false alarm sebesar 27 % dibandingkan metode statistik tradisional." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Implementasi prototipe pada sistem kontrol real‑time berhasil menurunkan downtime mesin sebesar 15 % dalam periode evaluasi tiga bulan." .

