# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Penggunaan algoritma dalam proses rekrutmen dapat memperkuat bias gender dan etnis, menghasilkan disparitas selection rate yang signifikan antara pelamar pria dan wanita." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Machine Learning / Fairness in AI / Rekrutmen (HR)" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Analisis Keadilan Algoritma Rekrutmen dengan Teknik Mitigasi Bias Berbasis Adversarial Learning" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Integrasi adversarial debiasing pada model klasifikasi (baseline Random Forest); evaluasi dengan cross‑validation 10‑fold dan metrik fairness (equalized odds)." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data historis perusahaan teknologi selama lima tahun, berisi 120.000 aplikasi pelamar kerja dengan atribut demografis, pendidikan, dan pengalaman kerja." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Cross‑validation 10‑fold; metrik fairness equalized odds; pengukuran akurasi (dengan catatan penurunan 1,2 %)." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Model baseline menunjukkan disparitas selection rate 18 % antara pria dan wanita." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Setelah penambahan komponen adversarial, disparitas berkurang menjadi 4 %." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Penurunan akurasi hanya 1,2 %, sehingga performa prediktif tetap terjaga." .

:Hasil_Penelitian_4 rdf:type :Result ;
    rdfs:label "Pendekatan adversarial terbukti efektif dalam mengurangi bias gender/etnis tanpa mengorbankan akurasi." .

