# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Proses rekayasa fitur manual pada model scoring kredit mikro memakan waktu dan bergantung pada keahlian domain, sehingga diperlukan metode otomatis untuk menghasilkan fitur yang efektif." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Kredit mikro, Machine Learning, Financial Technology" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Automatisasi Rekayasa Fitur Menggunakan Genetic Programming untuk Penilaian Kredit Mikro" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Genetic Programming untuk otomatisasi rekayasa fitur; evolusi populasi 500 individu selama 50 generasi dengan fitness berbasis AUC‑ROC pada model XGBoost; representasi kromosom mencakup operator aritmetika, logika, dan fungsi statistik." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data transaksi dari 250.000 nasabah mikro di Indonesia" .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Fitness berbasis AUC‑ROC pada model XGBoost; perbandingan AUC‑ROC sebelum (0.81) dan sesudah (0.87) penambahan fitur sintetis; pengukuran penurunan false negative rate sebesar 12 %; analisis interpretabilitas fitur baru." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "GP menghasilkan 23 fitur sintetis." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "AUC‑ROC model meningkat dari 0.81 menjadi 0.87." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "False negative rate berkurang sebesar 12 %." .

:Hasil_Penelitian_4 rdf:type :Result ;
    rdfs:label "Fitur baru menggabungkan pola pembayaran dan frekuensi transaksi." .

:Hasil_Penelitian_5 rdf:type :Result ;
    rdfs:label "Insight baru dari fitur tersebut dapat mendukung kebijakan kredit mikro." .

