# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Keterbatasan visibilitas data dalam rantai pasok menghambat pengambilan keputusan yang optimal." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Manajemen Rantai Pasok, Sistem Informasi, Machine Learning" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Model Prediktif Berbasis Machine Learning untuk Sistem Pendukung Keputusan pada Rantai Pasok" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Pengembangan sistem informasi pendukung keputusan (DSS) dengan algoritma pembelajaran mesin; pra‑pemrosesan fitur; pemilihan Model Gradient Boosting melalui evaluasi silang; evaluasi performa menggunakan metrik MAE." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data historis penjualan, inventaris, dan faktor eksternal yang dikumpulkan dari tiga perusahaan manufaktur." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "- Metrik MAE sebesar 3,2 % pada data uji.- Peningkatan akurasi perencanaan persediaan sebesar 15 % dibandingkan metode tradisional.- Pengurangan biaya stok berlebih sebesar 8,7 %." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Model Gradient Boosting menghasilkan MAE 3,2 % pada data uji." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Prototipe DSS meningkatkan akurasi perencanaan persediaan sebesar 15 % dibandingkan metode tradisional." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Prototipe DSS mengurangi biaya stok berlebih sebesar 8,7 %." .

:Hasil_Penelitian_4 rdf:type :Result ;
