# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Bagaimana pengaruh pelatihan soft skills (komunikasi, empati, manajemen konflik) terhadap kualitas layanan front office dan kepuasan kerja karyawan di hotel boutique, serta implikasinya terhadap kinerja operasional dan retensi tamu?" .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Manajemen perhotelan / Pengembangan sumber daya manusia / Kualitas layanan" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Evaluasi Dampak Program Pelatihan Soft Skills terhadap Kinerja Front Office di Hotel Boutique Surabaya" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Penelitian kuasi‑eksperimental dengan desain pre‑post, melibatkan grup intervensi dan grup kontrol; analisis covariance (ANCOVA) untuk menguji perbedaan signifikan." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data dari 60 karyawan front office (dua hotel boutique di Surabaya) yang diukur menggunakan indeks kualitas layanan (SERVQUAL) dan survei kepuasan karyawan, sebelum dan sesudah intervensi." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Analisis covariance (ANCOVA) dengan tingkat signifikansi p < 0,05; laporan persentase peningkatan pada dimensi keandalan layanan (+12,4 %) dan kepuasan kerja (+9,8 %)." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Pelatihan soft skills selama 8 minggu menghasilkan peningkatan signifikan pada keandalan layanan (+12,4 %) dan kepuasan kerja (+9,8 %) dibandingkan grup kontrol (p < 0,05)." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Investasi dalam pelatihan soft skills terbukti meningkatkan kinerja operasional front office." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Peningkatan kualitas layanan dan kepuasan karyawan berpotensi meningkatkan retensi tamu pada hotel boutique." .

