# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Keberadaan bias gender dalam model bahasa generatif berbahasa Indonesia yang dilatih pada korpus internet tidak terkontrol, yang dapat mereproduksi stereotip gender." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Pemrosesan Bahasa Alami (Natural Language Processing) – khususnya model bahasa generatif dan keadilan algoritmik." .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Deteksi dan Mitigasi Bias Gender pada Model Bahasa Generatif Bahasa Indonesia" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "- Analisis statistik pada output model GPT‑Indo menggunakan prompt khusus untuk mengidentifikasi bias gender.- Penerapan teknik debiasing berbasis counter‑factual data augmentation dan penalti loss selama fase fine‑tuning." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "- Benchmark bias gender yang terdiri dari 1.200 prompt.- Output model GPT‑Indo yang dihasilkan dari prompt tersebut." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "- Pengukuran penurunan skor bias (dengan perbandingan sebelum dan sesudah debiasing).- Evaluasi koherensi teks melalui perubahan perplexity (penurunan < 2%)." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Teknik debiasing berhasil menurunkan skor bias gender sebesar 34% tanpa mengorbankan koherensi teks." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Perplexity model hanya berkurang kurang dari 2%, menandakan tetapnya kualitas teks yang tinggi." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Pendekatan ini memberikan kontribusi praktis untuk pengembangan model bahasa Indonesia yang lebih adil dan bebas bias gender." .

