# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Bagaimana digitalisasi layanan publik memengaruhi efisiensi pengelolaan keuangan daerah, khususnya dalam meningkatkan efisiensi fiskal, mengurangi biaya administrasi, dan meningkatkan kepuasan warga pada pemerintah daerah di Jawa Barat." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "- Administrasi Publik / Kebijakan Publik- Keuangan Daerah / Fiskal- Pemerintahan Digital" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Digitalisasi Layanan Publik dan Efisiensi Fiskal: Analisis Kasus Pemerintah Daerah di Jawa Barat" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Analisis data sekunder dengan model Stochastic Frontier Analysis (SFA) untuk mengukur produktivitas total faktor; evaluasi implementasi sistem e‑procurement, e‑budgeting, dan portal layanan daring." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "- Data sekunder dari 12 kabupaten/kota Jawa Barat tahun 2016‑2023.- Survei online kepuasan warga yang dilakukan pada tahun 2023." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "- Pengukuran produktivitas total faktor menggunakan SFA.- Kuantifikasi perubahan efisiensi fiskal (+9,3 %) dan biaya administrasi (‑12 %).- Pengukuran perubahan kepuasan warga (+15 %) berdasarkan survei online." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Implementasi e‑procurement, e‑budgeting, dan portal layanan daring meningkatkan efisiensi fiskal sebesar 9,3 % dan menurunkan biaya administrasi sebesar 12 %." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Kepuasan warga meningkat 15 % setelah digitalisasi layanan publik." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Transformasi digital memperkuat akuntabilitas pemerintah daerah dan mengoptimalkan alokasi sumber daya, mendukung tujuan pembangunan daerah." .

