:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Meneliti bagaimana investasi pada pendidikan vokasi memengaruhi peningkatan nilai tambah industri manufaktur, percepatan pergeseran produksi ke segmen berteknologi tinggi, serta dampaknya terhadap pengurangan pengangguran struktural, sebagai upaya mempercepat upgrading industri manufaktur di Indonesia." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Ekonomi industri / Kebijakan pendidikan vokasi" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Pengembangan Modal Manusia sebagai Pendorong Upgrading Industri Manufaktur di Indonesia" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "- Analisis regresi berganda pada data time‑series 2000‑2022- Simulasi computable general equilibrium (CGE) untuk menilai skenario kebijakan" .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data time‑series 2000‑2022 (meliputi data lulusan vokasi, nilai tambah industri, rasio guru‑industri, dll.)" .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "- Estimasi koefisien regresi berganda untuk mengukur pengaruh investasi pendidikan vokasi terhadap nilai tambah industri- Simulasi CGE untuk menguji dampak kebijakan sinergi pada skenario ekonomi" .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Peningkatan 10 % lulusan program vokasi meningkatkan nilai tambah industri manufaktur sebesar 4,7 %." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Peningkatan lulusan vokasi mempercepat pergeseran produksi ke segmen berteknologi tinggi." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Wilayah dengan rasio guru‑industri tinggi menurunkan tingkat pengangguran struktural sebesar 2,1 %." .

:Hasil_Penelitian_4 rdf:type :Result ;
    rdfs:label "Rekomendasi kebijakan: sinergi antara lembaga pendidikan dan sektor industri untuk mempercepat proses upgrading ekonomi." .

