:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Mengevaluasi bagaimana liberalisasi perdagangan memengaruhi ketimpangan pendapatan di negara‑negara berkembang, khususnya apakah penurunan tarif berdampak pada distribusi pendapatan dan kelompok pekerja yang berbeda." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Ekonomi / Perdagangan Internasional / Ekonomi Pembangunan" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Liberalisasi Perdagangan dan Distribusi Pendapatan di Negara Berkembang: Bukti Empiris dari Asia Selatan" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Regresi panel Fixed Effects dengan variabel instrumental (tarif impor) untuk mengidentifikasi hubungan kausal antara liberalisasi perdagangan dan koefisien Gini." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data panel cross‑country yang mencakup 8 negara Asia Selatan selama periode 1995‑2020." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Identifikasi kausalitas melalui instrumen tarif impor; pengukuran efek tarif 5 % pada koefisien Gini (penurunan 0,018) serta analisis jalur (mediator) melalui upah manufaktur dan ekspor." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Penurunan tarif rata‑rata sebesar 5 % menurunkan koefisien Gini sebesar 0,018." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Efek penurunan Gini terutama terjadi lewat peningkatan upah di sektor manufaktur dan peningkatan ekspor." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Manfaat distribusi pendapatan lebih signifikan bagi pekerja terampil; pekerja tidak terampil justru mengalami penurunan pendapatan relatif." .

:Hasil_Penelitian_4 rdf:type :Result ;
    rdfs:label "Temuan menekankan kebutuhan akan kebijakan penyesuaian pasar tenaga kerja untuk mengatasi dampak distribusi negatif yang muncul selama proses liberalisasi perdagangan." .

