:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Pariwisata berkelanjutan / Pengembangan wilayah pesisir" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Strategi Diversifikasi Produk Wisata Berkelanjutan di Kawasan Pesisir" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Desain berbasis partisipatif; survei lapangan; analisis SWOT; model Analytic Hierarchy Process (AHP) untuk menentukan prioritas intervensi." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "- Survei lapangan dengan 250 responden wisatawan- Survei lapangan dengan 30 pelaku usaha" .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "- Pengukuran peningkatan kepuasan wisatawan sebesar 27 % dalam dua tahun- Pengukuran peningkatan pendapatan lokal sebesar 34 % dalam dua tahun- Pengukuran penurunan jejak karbon sebesar 15 % dalam dua tahun" .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Kombinasi ekowisata, agrowisata, dan festival budaya secara signifikan meningkatkan kepuasan wisatawan (27 %) dan pendapatan lokal (34 %) dalam periode dua tahun." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Kombinasi tersebut juga menurunkan jejak karbon sebesar 15 %." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Temuan memberikan rekomendasi kebijakan bagi pemerintah daerah untuk merumuskan paket wisata terintegrasi yang menyeimbangkan aspek ekonomi, sosial, dan lingkungan." .

