    rdfs:label "Tingkat konsumsi energi yang tinggi pada proses pemintalan dan pewarnaan menjadi tantangan utama operasional pabrik tekstil, sehingga diperlukan evaluasi kelayakan penerapan teknologi Internet of Things (IoT) untuk pemantauan energi secara real‑time." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Teknologi Informasi (IoT) • Industri Tekstil • Manajemen Energi" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Studi Kelayakan Implementasi Sistem IoT untuk Monitoring Energi di Pabrik Tekstil" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Implementasi prototipe sensor jaringan IoT pada 15 mesin utama, pengiriman data ke platform cloud, dan analisis data menggunakan algoritma clustering dalam pilot study selama dua bulan." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data energi real‑time yang dikumpulkan oleh sensor jaringan IoT pada 15 mesin utama selama dua bulan." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Identifikasi pola konsumsi berlebih (22 % mesin) melalui clustering, optimasi melalui penyesuaian parameter operasi, serta pengukuran penghematan energi (11,4 %) dan perhitungan ROI (14 bulan)." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "22 % mesin utama menunjukkan pola konsumsi energi berlebih." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Penyesuaian parameter operasi pada mesin tersebut menghasilkan penghematan energi sebesar 11,4 %." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "ROI tercapai dalam 14 bulan." .

:Hasil_Penelitian_4 rdf:type :Result ;
    rdfs:label "Studi menghasilkan kerangka kerja praktis bagi industri tekstil untuk mengadopsi teknologi IoT dalam meningkatkan efisiensi energi." .

