:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Lingkungan perkotaan / Klimatologi perkotaan, Remote sensing, Simulasi energi bangunan" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Pengaruh Atap Hijau terhadap Mitigasi Urban Heat Island di Jakarta: Analisis Remote Sensing dan Simulasi Energi" .

