# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Mengestimasi beban ekonomi yang ditimbulkan oleh banjir intensitas tinggi yang dipicu oleh perubahan pola curah hujan serta menilai biaya dan manfaat adaptasi di Kabupaten Bandung Barat." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Ekonomi Lingkungan / Kebijakan Adaptasi Banjir" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Kajian Ekonomi Lingkungan Terhadap Biaya Adaptasi Banjir di Kabupaten Bandung Barat" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Cost‑Benefit Analysis (CBA) dengan integrasi data kerugian properti, produktivitas pertanian, dan biaya mitigasi (pembangunan tanggul, sistem peringatan dini); dilengkapi dengan analisis sensitivitas terhadap skenario peningkatan curah hujan." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "- Data historis curah hujan (BMKG) 2005‑2020- Data kerusakan infrastruktur (Dinas PUPR) 2005‑2020" .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "- Perhitungan biaya total adaptasi (US$ 45 juta/tahun)- Perhitungan manfaat ekonomi yang dihindari (US$ 62 juta)- Rasio Benefit‑Cost (B/C) = 1,38- Analisis sensitivitas: peningkatan curah hujan 10 % → B/C = 1,62" .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Total biaya adaptasi diperkirakan US$ 45 juta per tahun." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Manfaat ekonomi yang dihindari diperkirakan US$ 62 juta, menghasilkan rasio B/C = 1,38 (manfaat > biaya)." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Pada skenario peningkatan curah hujan 10 %, rasio B/C meningkat menjadi 1,62, memperkuat argumen untuk investasi adaptasi." .

:Hasil_Penelitian_4 rdf:type :Result ;
    rdfs:label "Temuan menegaskan urgensi investasi adaptasi yang terukur untuk mengurangi beban ekonomi banjir di Kabupaten Bandung Barat." .

