# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Burnout pada perawat menjadi isu kritis yang memengaruhi kualitas perawatan dan retensi tenaga kerja." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Kesehatan / Keperawatan / Psikologi Kesehatan" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Program Mindfulness untuk Mengurangi Burnout pada Perawat Rumah Sakit" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Intervensi dengan desain pre‑post single‑group; program mindfulness selama 8 minggu dengan sesi 60 menit; analisis statistik menggunakan paired‑t test." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data dari 50 perawat unit medis yang mengisi Maslach Burnout Inventory (MBI) dan Perceived Stress Scale (PSS) sebelum dan sesudah program." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Paired‑t test untuk membandingkan skor burnout (emotional exhaustion, depersonalisasi, personal accomplishment) dan skor stres persepsi (PSS) sebelum vs. sesudah intervensi; signifikansi statistik p < 0,01." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Emotional exhaustion menurun dari 27,3 menjadi 15,8." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Depersonalisasi menurun dari 9,2 menjadi 5,1." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Personal accomplishment meningkat dari 34,5 menjadi 40,2." .

:Hasil_Penelitian_4 rdf:type :Result ;
    rdfs:label "Skor stres persepsi (PSS) menurun dari 22,5 menjadi 14,3." .

:Hasil_Penelitian_5 rdf:type :Result ;
    rdfs:label "Semua perubahan signifikan secara statistik (p < 0,01)." .

:Hasil_Penelitian_6 rdf:type :Result ;
    rdfs:label "Temuan mendukung integrasi program mindfulness dalam kebijakan kesejahteraan organisasi untuk meningkatkan kesejahteraan psikologis perawat." .

