# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Pertumbuhan instalasi energi terbarukan menimbulkan tantangan baru bagi stabilitas dinamis jaringan tenaga listrik, khususnya terkait penurunan margin stabilitas ketika pembangkit fotovoltaik dan turbin angin diintegrasikan ke sistem bertegangan tinggi." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Sistem tenaga listrik – Stabilitas dinamis – Energi terbarukan" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Analisis Stabilitas Dinamis pada Sistem Tenaga Listrik dengan Penambahan Sumber Energi Terbarukan" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Simulasi berbasis MATLAB/Simulink dengan penerapan eigenvalue analysis dan time‑domain simulation untuk mengevaluasi margin stabilitas setelah penambahan kapasitas terbarukan." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Model simulasi sistem 500 kV dengan skenario penambahan kapasitas terbarukan sebesar 30 % dari total beban." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "- Pengukuran margin stabilitas melalui eigenvalue analysis dan time‑domain simulation.- Analisis perubahan critical clearing time dan karakteristik oscillasi inter‑area mode (frekuensi 0,7 Hz).- Perbandingan margin stabilitas sebelum dan sesudah penerapan strategi kontrol inverter, serta pencapaian pemulihan hingga 95 % nilai referensi." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Penurunan critical clearing time sebesar 12 % setelah penambahan kapasitas terbarukan 30 % total beban." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Peningkatan amplitudo oscillasi inter‑area mode pada frekuensi 0,7 Hz." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Strategi kontrol koordinasi inverter dengan droop‑based governor berhasil memulihkan margin stabilitas hingga 95 % dari nilai referensi, menunjukkan efektivitas kontrol dalam mengatasi degradasi stabilitas akibat integrasi energi terbarukan." .

