:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Pengelolaan beban pada smart grid memerlukan pendekatan yang dapat secara bersamaan mempertimbangkan biaya operasional, emisi CO₂, dan kualitas daya (faktor daya) untuk meningkatkan efisiensi energi." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Smart Grid – Optimasi Multi‑Objektif – Energi & Lingkungan" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Optimasi Penjadwalan Beban pada Smart Grid Menggunakan Algoritma Evolusi Multi‑Objektif" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Model penjadwalan beban berbasis algoritma evolusi multi‑objektif NSGA‑II yang meminimalkan fungsi biaya total serta emisi CO₂ sambil menjaga faktor daya > 0,95." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data konsumsi listrik rumah tangga selama satu tahun di Kota Bandung, dipadukan dengan tarif dinamis dan sumber energi terdistribusi." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "- Pengukuran pengurangan biaya listrik rata‑rata (8,3 %).- Pengukuran penurunan emisi CO₂ (6,7 %) dibandingkan skema konvensional.- Analisis solusi Pareto optimal untuk fleksibilitas kebijakan operasional." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Model NSGA‑II berhasil menghasilkan jadwal beban yang menurunkan biaya listrik rata‑rata sebesar 8,3 % dan emisi CO₂ sebesar 6,7 % dibandingkan skema konvensional." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Faktor daya tetap terjaga di atas 0,95 selama seluruh periode simulasi." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Solusi Pareto optimal memberikan pilihan kebijakan yang dapat disesuaikan oleh operator sesuai dengan prioritas kebijakan energi daerah." .

