# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Menyelidiki dampak penerapan Test‑Driven Development (TDD) terhadap produktivitas dan kualitas perangkat lunak pada tim agile yang mengerjakan proyek web skala menengah." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Rekayasa Perangkat Lunak – Metodologi Pengembangan Agile / Test‑Driven Development" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Analisis Empiris Pengaruh Test‑Driven Development pada Tim Agile" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Studi empiris dengan pengumpulan data log commit, laporan bug, dan survei kepuasan selama enam bulan; analisis statistik menggunakan regresi linier berganda dan uji t‑student untuk membandingkan metrik defect density, lead time, dan tingkat kepuasan antara tim yang menggunakan TDD dan yang tidak." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Log commit, laporan bug, dan survei kepuasan tim yang dikumpulkan selama enam bulan dari lima tim agile yang mengerjakan proyek web skala menengah." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Pengukuran defect density, lead time, dan tingkat kepuasan developer; perbandingan statistik antara kelompok TDD dan non‑TDD menggunakan regresi linier berganda serta uji t‑student." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Defect density menurun 28 % pada tim yang menerapkan TDD." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Lead time meningkat 15 % pada tim TDD." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Kepuasan developer naik 12 poin pada skala Likert." .

:Hasil_Penelitian_4 rdf:type :Result ;
    rdfs:label "Bukti kuantitatif menunjukkan TDD dapat meningkatkan efisiensi proses pengembangan tanpa menambah beban kerja signifikan." .

