# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Kebutuhan untuk mempercepat proses delivery perangkat lunak dan meningkatkan kualitas layanan dengan mengurangi waktu penyebaran, frekuensi rollback, serta tingkat kegagalan integrasi pada pipeline DevOps." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Software Engineering – DevOps / Cloud Computing" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Otomatisasi Pipeline DevOps dengan Infrastructure as Code dan Orkestrasi Kontainer" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Pengembangan kerangka otomatisasi pipeline DevOps yang menggabungkan Infrastructure as Code (IaC) menggunakan Terraform dan orkestrasi kontainer dengan Kubernetes; implementasi pada dua aplikasi layanan mikro; evaluasi empiris melalui pengukuran metrik kunci selama siklus sprint tiga bulan." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data pengukuran (waktu penyebaran, frekuensi rollback, tingkat kegagalan integrasi) yang dikumpulkan dari dua aplikasi layanan mikro yang dikelola oleh tim DevSecOps selama tiga bulan sprint." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "- Pengukuran waktu penyebaran sebelum dan sesudah penerapan kerangka.- Pengukuran frekuensi rollback sebelum dan sesudah.- Pengukuran tingkat kegagalan integrasi sebelum dan sesudah.- Perbandingan hasil (before‑after) untuk menilai dampak pada stabilitas dan kecepatan delivery." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Waktu penyebaran rata‑rata berkurang dari 42 menit menjadi 9 menit." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Frekuensi rollback menurun sebesar 68 %." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Tingkat kegagalan integrasi turun dari 7 % menjadi 1,5 %, menunjukkan peningkatan stabilitas produksi." .

:Hasil_Penelitian_4 rdf:type :Result ;
    rdfs:label "Temuan mendukung adopsi praktik IaC dan kontainerisasi sebagai faktor kunci untuk mempercepat delivery dan meningkatkan kualitas layanan perangkat lunak." .

