:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Meneliti bagaimana proses digitalisasi ekonomi memengaruhi perubahan pola distribusi pendapatan nasional di lima negara ASEAN, serta implikasinya terhadap ketimpangan." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Ekonomi / Ekonomi Digital / Kebijakan Publik" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Dinamika Pendapatan Nasional dan Ketimpangan Distribusi di Era Digitalisasi" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Analisis data sekunder dengan model Vector Autoregression (VAR) dan penggunaan Gini coefficient sebagai indikator ketimpangan." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data sekunder dari World Bank dan International Telecommunication Union (ITU) untuk lima negara ASEAN tahun 2012‑2022." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Pengukuran efek kuantitatif: peningkatan indeks digitalisasi 10 poin dikaitkan dengan pertumbuhan pendapatan nasional rata‑rata 1,8 % dan kenaikan Gini coefficient sebesar 0,02 poin." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Indeks digitalisasi yang naik 10 poin berhubungan dengan pertumbuhan pendapatan nasional rata‑rata 1,8 %." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Kenaikan yang sama juga meningkatkan Gini coefficient sebesar 0,02 poin, menandakan potensi peningkatan ketimpangan." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Diperlukan kebijakan inklusif, khususnya program pelatihan digital bagi tenaga kerja informal, untuk mengurangi dampak distribusi pendapatan yang tidak merata." .

