:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Menilai sejauh mana kebijakan fiskal yang diterapkan pemerintah Indonesia berhasil meredam dampak ekonomi akibat pandemi COVID‑19 pada tahun 2020‑2021 serta mengidentifikasi risiko jangka panjang terhadap defisit fiskal dan beban utang publik." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Ekonomi – Kebijakan Fiskal / Ekonomi Pembangunan" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Analisis Kebijakan Fiskal dalam Menanggulangi Dampak Ekonomi Pandemi COVID-19 di Indonesia" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Analisis input‑output dengan simulasi multiplikator fiskal berbasis Model SAM (Social Accounting Matrix)." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data input berasal dari Badan Pusat Statistik dan laporan Kementerian Keuangan." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Simulasi menghasilkan metrik perubahan output sektor manufaktur (↑ 3,2 %), output sektor jasa (↑ 2,7 %), penurunan pengangguran (↓ 0,9 poin persentase), serta penilaian risiko peningkatan defisit fiskal dan beban utang publik." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Paket stimulus sebesar 2,5 % PDB meningkatkan output sektor manufaktur sebesar 3,2 % dan sektor jasa sebesar 2,7 %." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Pengangguran menurun sebesar 0,9 poin persentase." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Efek jangka panjang menimbulkan risiko peningkatan defisit fiskal yang dapat memperbesar beban utang publik." .

:Hasil_Penelitian_4 rdf:type :Result ;
    rdfs:label "Rekomendasi kebijakan: penyesuaian pajak progresif dan peningkatan efisiensi belanja publik untuk menjaga keberlanjutan fiskal." .

