# Definisi Node Non-Entity
:Masalah_Penelitian rdf:type :Problem ;
    rdfs:label "Kurangnya pemahaman yang terkuantifikasi tentang sejauh mana pendidikan tinggi berkontribusi pada inovasi dan pertumbuhan ekonomi di negara‑negara berkembang, khususnya Indonesia, Vietnam, dan Filipina, serta faktor‑faktor apa yang memperkuat kontribusi tersebut." .

:Topik_Penelitian rdf:type :Topic ;
    rdfs:label "Ekonomi pembangunan / Kebijakan pendidikan tinggi / Studi inovasi" .

:Judul_Penelitian rdf:type :Title ;
    rdfs:label "Peran Pendidikan Tinggi dalam Mendorong Inovasi dan Pertumbuhan Ekonomi di Negara Berkembang" .

:Metodologi_Penelitian rdf:type :Methodology ;
    rdfs:label "Metode kuantitatif dengan regresi panel data dinamis; pembangunan indeks inovasi nasional yang menggabungkan data paten, publikasi ilmiah, dan investasi R&D." .

:Sumber_Data_Penelitian rdf:type :DataSource ;
    rdfs:label "Data panel negara Indonesia, Vietnam, dan Filipina selama tahun 2005‑2020; mencakup rasio lulusan perguruan tinggi, pertumbuhan PDB tahunan, skor inovasi, serta variabel‑variabel paten, publikasi ilmiah, dan investasi R&D." .

:Indikator_Evaluasi rdf:type :EvaluationIndicator ;
    rdfs:label "Analisis regresi panel untuk menguji asosiasi statistik antara rasio lulusan perguruan tinggi dengan pertumbuhan PDB tahunan dan skor inovasi; identifikasi faktor penentu utama melalui analisis tambahan (kualitas kurikulum, kolaborasi industri‑akademik)." .

:Hasil_Penelitian_1 rdf:type :Result ;
    rdfs:label "Setiap kenaikan 1 % rasio lulusan perguruan tinggi terkait dengan peningkatan pertumbuhan PDB tahunan sebesar 0,27 % dan peningkatan skor inovasi sebesar 0,15 poin." .

:Hasil_Penelitian_2 rdf:type :Result ;
    rdfs:label "Kualitas kurikulum dan kolaborasi industri‑akademik muncul sebagai faktor penentu utama yang memperkuat dampak pendidikan tinggi pada inovasi." .

:Hasil_Penelitian_3 rdf:type :Result ;
    rdfs:label "Kebijakan yang menekankan reformasi kurikulum serta peningkatan pendanaan penelitian di institusi pendidikan tinggi dianggap krusial untuk memaksimalkan kontribusi pendidikan tinggi terhadap inovasi dan pertumbuhan ekonomi di negara‑negara berkembang." .
